START TRANSACTION;

CREATE TABLE "PropertyServiceRates" (
    "RateId" integer GENERATED BY DEFAULT AS IDENTITY,
    "PropertyId" integer NOT NULL,
    "ServiceId" integer NOT NULL,
    "Price" numeric(18,2) NOT NULL,
    "UnitCode" text NOT NULL,
    "BillingBasis" text NOT NULL,
    "EffectiveFrom" date NOT NULL,
    "EffectiveTo" date,
    CONSTRAINT "PK_PropertyServiceRates" PRIMARY KEY ("RateId"),
    CONSTRAINT "AK_PropertyServiceRates_RateId_ServiceId" UNIQUE ("RateId", "ServiceId"),
    CONSTRAINT "CK_PropertyServiceRates_EffectiveFrom_MonthStart" CHECK (EXTRACT(DAY FROM "EffectiveFrom") = 1),
    CONSTRAINT "CK_PropertyServiceRates_EffectiveRange" CHECK ("EffectiveTo" IS NULL OR "EffectiveTo" > "EffectiveFrom"),
    CONSTRAINT "CK_PropertyServiceRates_EffectiveTo_MonthStart" CHECK ("EffectiveTo" IS NULL OR EXTRACT(DAY FROM "EffectiveTo") = 1),
    CONSTRAINT "CK_PropertyServiceRates_Price_NonNegative" CHECK ("Price" >= 0),
    CONSTRAINT "CK_PropertyServiceRates_UnitBillingBasis" CHECK (("UnitCode" = 'kwh' AND "BillingBasis" = 'usage') OR ("UnitCode" = 'm3' AND "BillingBasis" = 'usage') OR ("UnitCode" = 'room_month' AND "BillingBasis" = 'fixed_room') OR ("UnitCode" = 'person_month' AND "BillingBasis" = 'occupant') OR ("UnitCode" = 'vehicle_month' AND "BillingBasis" = 'vehicle')),
    CONSTRAINT "FK_PropertyServiceRates_Properties_PropertyId" FOREIGN KEY ("PropertyId") REFERENCES "Properties" ("PropertyId") ON DELETE RESTRICT,
    CONSTRAINT "FK_PropertyServiceRates_Services_ServiceId" FOREIGN KEY ("ServiceId") REFERENCES "Services" ("ServiceId") ON DELETE RESTRICT
);

CREATE INDEX "IX_PropertyServiceRates_PropertyId_ServiceId_EffectiveFrom" ON "PropertyServiceRates" ("PropertyId", "ServiceId", "EffectiveFrom");

CREATE INDEX "IX_PropertyServiceRates_ServiceId" ON "PropertyServiceRates" ("ServiceId");

CREATE EXTENSION IF NOT EXISTS btree_gist;

ALTER TABLE "PropertyServiceRates"
ADD CONSTRAINT "EX_PropertyServiceRates_NoOverlappingPeriods"
EXCLUDE USING gist (
    "PropertyId" WITH =,
    "ServiceId" WITH =,
    daterange("EffectiveFrom", "EffectiveTo", '[)') WITH &&
);

ALTER TABLE "PropertyServiceRates" ENABLE ROW LEVEL SECURITY;

